<script setup>
import { inject, ref } from 'vue'
import { UiSelect } from '../components/ui/index.js'
import TemperatureControl from '../components/ui/TemperatureControl.vue'
import { settings, layout, aiReady, prefsError } from '../state/settings.js'
const showKey = ref(false), loggingOut = ref(false), logoutError = ref(''), identity = inject('identity')
const providers = [{ value: 'openai-compatible', label: 'OpenAI 兼容接口' }, { value: 'anthropic-compatible', label: 'Anthropic 兼容接口' }]
async function logout() { loggingOut.value = true; logoutError.value = ''; try { await identity.logout() } catch (error) { logoutError.value = error.message } finally { loggingOut.value = false } }
</script>
<template><p v-if="prefsError" class="error-banner">{{ prefsError }}</p><section class="surface settings-form"><h3>AI 模型 <span class="chip">{{ aiReady() ? '已填写' : '待配置' }}</span></h3><div class="settings-field"><label class="settings-field-label">接口类型</label><UiSelect v-model="settings.provider" :options="providers" aria-label="接口类型" /></div><label>接口地址<input v-model.trim="settings.baseUrl" type="url" placeholder="https://你的模型服务地址/v1" /><small>填写 API 基础地址，程序会追加对应的对话接口路径。</small></label><label>API 密钥<div class="key-input"><input v-model.trim="settings.apiKey" :type="showKey ? 'text' : 'password'" autocomplete="off" placeholder="输入 API Key" /><button @click="showKey = !showKey">{{ showKey ? '隐藏' : '显示' }}</button></div></label><div class="form-columns"><label>模型名称<input v-model.trim="settings.model" placeholder="填写服务提供的模型 ID" /></label></div><div class="temperature-field"><span class="temperature-label">温度</span><TemperatureControl v-model="settings.temperature" /></div><p class="save-note"><span class="status-dot" />修改自动保存。连接情况会在首次对话时验证。</p></section><section class="surface settings-form"><h3>工作台</h3><label class="checkbox-label"><input v-model="layout.aiVisible" type="checkbox" />显示右侧工作助理</label><p class="muted">拖动中间分隔条可调整宽度，拖到最右侧可收起工作助理。</p></section><section class="surface settings-form"><h3>登录身份</h3><p>{{ identity.state.owner.displayName }} · {{ identity.state.connector.name }}</p><p class="muted">用户 ID：{{ identity.state.owner.id }}<template v-if="identity.state.owner.orgId"> · 组织：{{ identity.state.owner.orgId }}</template></p><p v-if="logoutError" class="error-banner">{{ logoutError }}</p><button :disabled="loggingOut" @click="logout">{{ loggingOut ? '正在保存并退出…' : '退出登录 / 切换用户' }}</button></section></template>
